//! Static MetaObject data model (ADR 0002): read-only descriptors generated by
//! `rt-macros` at derive time; no runtime assembly.

use core::any::TypeId;

/// A type referenced by a descriptor: display name plus exact identity.
#[derive(Debug, PartialEq, Eq)]
pub struct TypeRef {
    /// Display-only rendering of the type; identity lives in `id`.
    pub name: &'static str,
    pub id: TypeId,
}

/// A named occurrence objects may emit; delivered, never coalesced.
#[derive(Debug, PartialEq, Eq)]
pub struct SignalDescriptor {
    pub name: &'static str,
    pub args: &'static [TypeRef],
}

/// A named operation offered in response to signals.
#[derive(Debug, PartialEq, Eq)]
pub struct SlotDescriptor {
    pub name: &'static str,
    pub args: &'static [TypeRef],
    /// Unit (`()`) when the slot returns nothing.
    pub ret: TypeRef,
}

/// Named state where only the latest value matters.
#[derive(Debug, PartialEq, Eq)]
pub struct PropertyDescriptor {
    pub name: &'static str,
    pub ty: TypeRef,
}

/// The static description of a kind of object: members and parent kind.
#[derive(Debug)]
pub struct MetaObject {
    pub type_name: &'static str,
    /// Parent kind link as a thunk over its own static MetaObject.
    pub parent: Option<fn() -> &'static MetaObject>,
    pub signals: &'static [SignalDescriptor],
    pub slots: &'static [SlotDescriptor],
    pub properties: &'static [PropertyDescriptor],
}

impl MetaObject {
    /// The parent kind's MetaObject, at the same address `Parent::meta()` returns.
    pub fn parent_meta(&self) -> Option<&'static MetaObject> {
        self.parent.map(|parent| parent())
    }
}

/// A kind of object with a static MetaObject; implemented by `#[derive(Object)]`.
///
/// # Example
/// ```
/// use rt_core::{Object, object_impl};
///
/// #[derive(Object)]
/// struct Widget;
///
/// #[object_impl]
/// impl Widget {
///     #[signal]
///     fn pressed(&self, button: u8);
///
///     #[slot]
///     fn release(&mut self) {}
/// }
///
/// let meta = Widget::meta();
/// assert_eq!(meta.signals[0].name, "pressed");
/// assert_eq!(meta.slots[0].name, "release");
/// ```
pub trait Object: crate::property::PropertyInputs {
    /// The static description of this kind of object; no runtime allocation.
    fn meta() -> &'static MetaObject;
}

/// Signal/slot descriptors harvested from the type's `#[object_impl]` block.
/// Every `#[derive(Object)]` type needs exactly one `#[object_impl]` impl.
pub trait ObjectInputs {
    const SIGNALS: &'static [SignalDescriptor];
    const SLOTS: &'static [SlotDescriptor];
}
